function syncLibrary(state){libraryState=state;const records=new Map(state.tracks.map(r=>[r.id,r]));for(const cue of items.filter(c=>c.libraryId)){const record=records.get(cue.libraryId);cue.missing=!record||record.missing;if(record){if(!cue.sourceTitle||cue.name===cue.sourceTitle)cue.name=record.name;cue.sourceTitle=record.name;cue.artist=record.artist;cue.album=record.album;if(cue.sourceHash&&record.audioHash&&cue.sourceHash!==record.audioHash){cue.normalizationDb=0;cue.normalizationInfo=null;cue.needsReview=true}cue.sourceHash=record.audioHash||cue.sourceHash;cue.sourceRevision=record.revision||0;cue.duration=record.duration||cue.duration}}if(libraryOpen&&$('#library-content'))drawLibraryList();drawBoard();if(state.progress)status(`素材库 ${state.progress.done}/${state.progress.total} · ${state.progress.name}`)}
