$('#panic-header').onclick=()=>$('#panic').click();$('#compact-mode').onclick=()=>{A.compact=!A.compact;drawBoard();base.save()};$('#monitor-mode').onclick=toggleMonitor;$('#monitor-workspace-open').onclick=openMonitor;$('#group-add').onclick=addGroup;$('#page-add').onclick=addPage;$('#page-manage').onclick=managePage;$('#native-library').onclick=openLibrary;$('#page-catalog').onclick=openCatalog;$('#schedule-open').onclick=openSchedule;$('#theme-open').onclick=openThemes;$('#controller-open').onclick=openController;$('#board-search').oninput=drawBoard;$('#page-prev').onclick=()=>stepPage(-1);$('#page-next').onclick=()=>stepPage(1);$('#reset-used').onclick=()=>{if(monitor)A.monitorUsed=[];else A.used=A.used.filter(id=>!pageItems().some(c=>c.id===id));drawBoard();base.save()};$('#shuffle-mode').onclick=()=>{if(monitor)A.monitorShuffle=!A.monitorShuffle;else A.shuffle=!A.shuffle;drawBoard();base.save()};$('#list-loop').onclick=()=>{if(monitor)A.monitorListLoop=!A.monitorListLoop;else A.listLoop=!A.listLoop;drawBoard();base.save()};$('#go').onclick=()=>go();
