$('#pads').ondragover=e=>{e.preventDefault();e.dataTransfer.dropEffect='move'};$('#pads').ondrop=e=>{e.preventDefault();if(!canEdit())return;const slot=Number(e.target.closest('[data-slot]')?.dataset.slot);if(!Number.isInteger(slot))return;const cue=e.dataTransfer.getData('application/x-stagecue-cue'),library=e.dataTransfer.getData('application/x-stagecue-library');if(cue)moveCue(cue,slot);else if(library)addLibraryCue(library,slot);else if(e.dataTransfer.files.length){nextSlot=slot;$('#files').files=e.dataTransfer.files;$('#files').dispatchEvent(new Event('change',{bubbles:true}))}};
$('#board-navigation').ondragstart=e=>{if(locked){e.preventDefault();return}const page=e.target.closest('[data-page]'),group=e.target.closest('[data-group]');if(page)e.dataTransfer.setData('application/x-stagecue-page',page.dataset.page);else if(group)e.dataTransfer.setData('application/x-stagecue-group',group.dataset.group)};
$('#board-navigation').ondragover=e=>e.preventDefault();$('#board-navigation').ondrop=e=>{e.preventDefault();if(!canEdit())return;const pageId=e.dataTransfer.getData('application/x-stagecue-page'),groupId=e.dataTransfer.getData('application/x-stagecue-group'),targetPage=e.target.closest('[data-page]'),targetGroup=e.target.closest('[data-group]');if(pageId&&targetGroup){const from=A.groups.find(g=>g.pages.some(p=>p.id===pageId)),to=A.groups.find(g=>g.id===targetGroup.dataset.group),page=from?.pages.find(p=>p.id===pageId);if(page&&to){from.pages=from.pages.filter(p=>p!==page);const index=targetPage?to.pages.findIndex(p=>p.id===targetPage.dataset.page):to.pages.length;to.pages.splice(index<0?to.pages.length:index,0,page);A.group=to.id;A.page=page.id;normalizeLayout()}}else if(groupId&&targetGroup){const from=A.groups.findIndex(g=>g.id===groupId),to=A.groups.findIndex(g=>g.id===targetGroup.dataset.group);if(from>=0&&to>=0)A.groups.splice(to,0,A.groups.splice(from,1)[0])}drawBoard();base.save()};
const saveSoon=()=>{clearTimeout(saveSoon.timer);saveSoon.timer=setTimeout(()=>base.save(),500)};$('#quick-home-name').oninput=()=>{A.scores.homeName=short($('#quick-home-name').value);saveSoon()};$('#quick-away-name').oninput=()=>{A.scores.awayName=short($('#quick-away-name').value);saveSoon()};$('#quick-notes').oninput=()=>{A.notes=$('#quick-notes').value.slice(0,50000);saveSoon()};document.querySelector('.ad-score').onclick=e=>{const button=e.target.closest('[data-score]');if(button){A.scores[button.dataset.score]=clamp(A.scores[button.dataset.score]+Number(button.dataset.amount),0,999);drawQuick();base.save()}};
