const oldModal=showModal;showModal=(title,html)=>{activeEditor=null;libraryOpen=false;$('#modal .dialog').classList.remove('ad-editor-dialog','ad-wide-dialog');$('#modalBody').onclick=null;return oldModal(title,html)};
setTrackVolume=(id,value)=>{if(!canEdit())return;const cue=items.find(c=>c.id===id);if(!cue)return;const volume=clamp(value/100,0,1);if(monitor){A.drafts[id]={...(A.drafts[id]||{}),volume};if(preview?.item.id===id){preview.item={...preview.item,volume};updatePrivateLevel()}}else{cue.volume=volume;for(const voice of voices)if(voice.item.id===id&&!voice.disposed){voice.item.volume=volume;ramp(voice.trackGain.gain,trackGain(voice.item),.03)}}base.save()};
